`timescale 1ns/1ps
module tb_operator_state_endpoint_v3;
 logic clk_i,rst_ni;initial begin clk_i=0;rst_ni=0;end always #1 clk_i=~clk_i;logic req_valid_i,req_ready_o;logic[7:0]req_opcode_i,req_variant_i;logic[15:0]req_tag_i;logic[7:0]req_parent_phase_i,req_terminal_phase_i;logic config_valid_i,config_ready_o;logic[63:0]state_address_i,window_base_i,state_stride_i;logic[511:0]write_data_i;logic[31:0]decay_i;logic[127:0]conv_weights_i;
 logic mem_req_valid_o,mem_req_ready_i,mem_req_write_o;logic[63:0]mem_req_addr_o;logic[511:0]mem_req_wdata_o;logic[63:0]mem_req_wstrb_o;logic mem_rsp_valid_i,mem_rsp_ready_o;logic[511:0]mem_rsp_rdata_i;logic mem_rsp_error_i;logic result_valid_o,result_ready_i;logic[511:0]result_data_o;logic[4:0]exception_flags_o;logic completion_valid_o,completion_ready_i;logic[15:0]completion_tag_o;logic[7:0]completion_parent_phase_o,completion_terminal_phase_o,completion_status_o;logic[15:0]generation_o;logic[511:0]mem[0:63];integer mem_reads,mem_writes,successes,errors;
 operator_state_endpoint_v3 dut(.*);assign mem_req_ready_i=!mem_rsp_valid_i;
 always_ff@(posedge clk_i)begin if(!rst_ni)begin mem_rsp_valid_i<=0;mem_rsp_rdata_i<=0;mem_rsp_error_i<=0;mem_reads<=0;mem_writes<=0;for(int i=0;i<64;i++)mem[i]<=0;end else begin if(mem_rsp_valid_i&&mem_rsp_ready_o)mem_rsp_valid_i<=0;if(mem_req_valid_o&&mem_req_ready_i)begin if(mem_req_addr_o[5:0]!=0||mem_req_wstrb_o!=64'hffffffffffffffff)$fatal(1,"mem alignment");mem_rsp_valid_i<=1;mem_rsp_error_i<=0;if(mem_req_write_o)begin mem[mem_req_addr_o[11:6]]<=mem_req_wdata_o;mem_writes<=mem_writes+1;mem_rsp_rdata_i<=0;end else begin mem_rsp_rdata_i<=mem[mem_req_addr_o[11:6]];mem_reads<=mem_reads+1;end end end end
 task run(input[7:0]op,input[15:0]txn,input logic want_config,input logic want_result,input[511:0]expected,input[7:0]expected_status);begin @(negedge clk_i);req_opcode_i=op;req_tag_i=txn;req_valid_i=1;do @(posedge clk_i);while(!req_ready_o);@(negedge clk_i);req_valid_i=0;if(want_config)begin config_valid_i=1;do @(posedge clk_i);while(!config_ready_o);@(negedge clk_i);config_valid_i=0;end if(want_result)begin wait(result_valid_o);if(result_data_o!==expected)$fatal(1,"result op=%h got=%h expected=%h",op,result_data_o,expected);repeat(2)@(posedge clk_i);if(!result_valid_o)$fatal(1,"result stall");result_ready_i=1;@(posedge clk_i);@(negedge clk_i);result_ready_i=0;end wait(completion_valid_o);if(completion_status_o!=expected_status||completion_tag_o!=txn||completion_parent_phase_o!=8'h56||completion_terminal_phase_o!=8'h78)$fatal(1,"completion op=%h status=%0d",op,completion_status_o);repeat(2)@(posedge clk_i);if(!completion_valid_o)$fatal(1,"completion stall");completion_ready_i=1;@(posedge clk_i);@(negedge clk_i);completion_ready_i=0;if(expected_status==0)successes=successes+1;else errors=errors+1;end endtask
 initial begin repeat(300000)@(posedge clk_i);$fatal(1,"timeout");end
 initial begin req_valid_i=0;req_opcode_i=0;req_variant_i=3;req_tag_i=0;req_parent_phase_i=8'h56;req_terminal_phase_i=8'h78;config_valid_i=0;state_address_i=0;window_base_i=0;state_stride_i=64;write_data_i=0;decay_i=32'h3f000000;conv_weights_i={32'h00000000,32'h00000000,32'h00000000,32'h3f800000};result_ready_i=0;completion_ready_i=0;successes=0;errors=0;repeat(5)@(posedge clk_i);rst_ni=1;
  for(int t=1;t<=10;t++)begin run(8'h64,t,0,0,0,0);state_address_i=0;write_data_i={16{32'h3f800000}};run(8'h61,t,1,0,0,0);state_address_i=64;write_data_i={16{32'h40000000}};run(8'h61,t,1,0,0,0);state_address_i=128;write_data_i={16{32'h40400000}};run(8'h61,t,1,0,0,0);state_address_i=192;write_data_i={16{32'h40800000}};run(8'h61,t,1,0,0,0);state_address_i=256;window_base_i=0;run(8'h63,t,1,1,{16{32'h3f800000}},0);state_address_i=256;run(8'h62,t,1,1,{16{32'h3f000000}},0);run(8'h60,t,1,1,{16{32'h3f000000}},0);run(8'h65,t,0,0,0,0);run(8'h60,t,1,1,{16{32'h3f000000}},0);end
  run(8'h64,16'h20,0,0,0,0);state_address_i=0;write_data_i={16{32'h41100000}};run(8'h61,16'h20,1,0,0,0);run(8'h66,16'h20,0,0,0,0);run(8'h60,16'h20,1,1,{16{32'h3f800000}},0);run(8'h65,16'h21,0,0,0,7);
  if(successes!=104||errors!=1||mem_writes!=60||mem_reads!=11||generation_o!=11)$fatal(1,"counts success=%0d err=%0d wr=%0d rd=%0d gen=%0d",successes,errors,mem_writes,mem_reads,generation_o);
  $display("OPERATOR_STATE_ENDPOINT_V3_PASS successful=104 errors=1 mem_writes=60 mem_reads=11 generation=11 opcodes=7");$finish;end
endmodule
